def render_operations_ui():
    return r"""
<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>KIS Trading LAB · Control Center</title><style>
:root{color-scheme:dark;--bg:#070b13;--side:#090f1a;--panel:#0e1726;--panel2:#111d30;--line:#213049;--text:#edf3fb;--muted:#8290a5;--blue:#4f86ff;--cyan:#42c7d9;--green:#22c99a;--red:#ff5870;--amber:#f4b84a;--shadow:0 18px 50px #0005}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:Inter,Pretendard,"Noto Sans KR",system-ui,sans-serif;font-variant-numeric:tabular-nums}button,input,select{font:inherit}.shell{min-height:100vh;display:grid;grid-template-columns:244px minmax(0,1fr)}aside{position:sticky;top:0;height:100vh;padding:20px 14px;border-right:1px solid var(--line);background:linear-gradient(180deg,#0b1321,#080d16)}.brand{display:flex;align-items:center;gap:12px;padding:0 9px 22px}.mark{width:38px;height:38px;display:grid;place-items:center;border-radius:11px;background:linear-gradient(145deg,#ff5a70,#d92845);font-weight:900;box-shadow:0 0 25px #ff506044}.brand b{font-size:14px}.brand small{display:block;color:var(--muted);margin-top:3px}.nav{display:grid;gap:5px}.nav button{border:0;background:transparent;color:#8c9bb0;padding:11px 12px;border-radius:9px;text-align:left;cursor:pointer;font-weight:750}.nav button:hover{background:#111d2e;color:#dce6f4}.nav button.active{background:linear-gradient(90deg,#1d3760,#14243b);color:#fff;box-shadow:inset 3px 0 var(--blue)}.nav i{display:inline-grid;width:25px;font-style:normal}.aside-foot{position:absolute;left:14px;right:14px;bottom:18px}.mode{border:1px solid #604719;background:#211a0c;color:#f7c969;border-radius:9px;padding:10px;font-size:11px}.back{display:block;margin-top:9px;text-decoration:none;color:#95a5bb;font-size:11px;padding:9px}main{min-width:0}.top{height:68px;display:flex;align-items:center;justify-content:space-between;padding:0 25px;border-bottom:1px solid var(--line);background:#080e18d9;backdrop-filter:blur(12px);position:sticky;top:0;z-index:5}.title h1{font-size:17px;margin:0}.title p{color:var(--muted);font-size:11px;margin:4px 0 0}.top-actions{display:flex;align-items:center;gap:9px}.health{font-size:11px;color:var(--green)}.health:before{content:"";display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor;margin-right:7px;box-shadow:0 0 9px currentColor}.btn{border:1px solid var(--line);background:#142136;color:#dbe6f4;padding:9px 12px;border-radius:8px;cursor:pointer;font-size:11px;font-weight:800}.btn:hover{filter:brightness(1.15)}.btn.primary{background:linear-gradient(135deg,#477ff5,#285dca);border-color:#477ff5;color:#fff}.btn.danger{background:#321724;color:#ff788a;border-color:#663042}.content{padding:18px 22px 35px;max-width:1600px;margin:auto}.notice{display:none;margin-bottom:12px;padding:11px 13px;border:1px solid #285141;background:#10251f;border-radius:9px;font-size:12px;color:#7ce3c1}.notice.show{display:block}.page{display:none}.page.active{display:block}.page-head{display:flex;justify-content:space-between;align-items:end;margin:3px 0 15px}.page-head h2{font-size:20px;margin:0}.page-head p{font-size:11px;color:var(--muted);margin:5px 0 0}.kpis{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.card,.panel{background:linear-gradient(145deg,var(--panel2),var(--panel));border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow)}.kpi{padding:15px;min-height:91px;position:relative;overflow:hidden}.kpi:after{content:"";position:absolute;width:72px;height:72px;border-radius:50%;right:-30px;top:-31px;background:#4f86ff12}.label{font-size:10px;color:var(--muted);font-weight:700}.value{font-size:23px;font-weight:900;margin-top:11px}.value small{font-size:10px;color:var(--muted);font-weight:600}.grid{display:grid;grid-template-columns:1.2fr .8fr;gap:11px;margin-top:11px}.grid.equal{grid-template-columns:1fr 1fr}.panel{padding:15px;min-width:0}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}.panel h3{font-size:13px;margin:0}.muted{color:var(--muted);font-size:11px}.state-box{display:flex;align-items:center;justify-content:space-between;background:#09111d;border:1px solid #1c2a40;border-radius:10px;padding:13px}.state-box strong{font-size:15px}.pill{display:inline-flex;padding:5px 8px;border-radius:999px;background:#22324a;color:#b9c6d8;font-size:9px;font-weight:900}.pill.ok{background:#123228;color:#62dcb7}.pill.fail{background:#371824;color:#ff7185}.pill.partial{background:#3a2c12;color:#f4c96b}.job-list{display:grid;gap:7px}.job{display:grid;grid-template-columns:1fr auto;align-items:center;gap:10px;border:1px solid #1d2b40;background:#0a121f;border-radius:9px;padding:10px}.job b{font-size:11px}.job small{display:block;color:var(--muted);font-size:9px;margin-top:4px}.table-wrap{overflow:auto;border:1px solid #1e2c42;border-radius:9px}table{width:100%;border-collapse:collapse;min-width:560px}th{font-size:9px;text-transform:uppercase;letter-spacing:.05em;color:#72839b;background:#0a121e;text-align:left;padding:9px}td{font-size:11px;padding:10px 9px;border-top:1px solid #19263a}tr:hover td{background:#111d2d}.num{text-align:right}.BUY{color:var(--red);font-weight:900}.SELL{color:#67a4ff;font-weight:900}.HOLD{color:#aab5c5;font-weight:900}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.field-label{font-size:10px;color:#9ba9bb}.field{display:block;width:100%;margin-top:5px;padding:10px;border:1px solid #283750;border-radius:8px;background:#080f1a;color:#fff;outline:none}.field:focus{border-color:var(--blue);box-shadow:0 0 0 3px #4f86ff20}.switch-row{display:flex;align-items:center;justify-content:space-between;padding:12px 0}.universe-row{display:grid;grid-template-columns:36px 1fr 130px 80px auto;gap:8px;align-items:center;border-top:1px solid #1b293d;padding:9px 2px}.universe-row:first-child{border-top:0}.universe-row input[type=number],.universe-row select{padding:7px}.stock b{font-size:11px}.stock small{display:block;color:var(--muted);font-size:9px}.bar{height:6px;background:#1b293b;border-radius:9px;overflow:hidden;margin-top:6px}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--blue),var(--cyan))}.empty{text-align:center;color:var(--muted);font-size:11px;padding:22px}.toolbar{display:flex;gap:7px;flex-wrap:wrap}.log-filter{display:flex;gap:6px}.log-filter button.active{border-color:var(--blue);color:white}.pipeline{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.stage{border:1px solid #203049;border-radius:10px;background:#09111d;padding:12px;text-align:center}.stage span{display:grid;place-items:center;margin:0 auto 8px;width:28px;height:28px;border-radius:50%;background:#1d3355;color:#84adff;font-weight:900}.stage b{font-size:11px}.arrow{display:none}
@media(max-width:1050px){.shell{grid-template-columns:76px minmax(0,1fr)}aside{padding:16px 9px}.brand{padding:0 9px 20px}.brand>div:last-child,.nav button span,.aside-foot{display:none}.nav button{text-align:center}.nav i{width:auto;font-size:17px}.grid{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(3,1fr)}}@media(max-width:680px){.shell{display:block}aside{position:fixed;bottom:0;top:auto;z-index:20;width:100%;height:58px;padding:5px;border:0;border-top:1px solid var(--line)}.brand,.aside-foot{display:none}.nav{grid-template-columns:repeat(5,1fr)}.nav button{padding:7px 2px;font-size:9px}.nav i{display:block;font-size:15px;margin:auto}.nav button span{display:block}.top{height:59px;padding:0 12px}.title p,.health{display:none}.content{padding:12px 9px 76px}.page-head h2{font-size:17px}.kpis{grid-template-columns:1fr 1fr}.kpi{min-height:78px}.value{font-size:19px}.grid.equal{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.universe-row{grid-template-columns:30px 1fr 70px}.universe-row select{display:none}.universe-row .save-universe{grid-column:3}.pipeline{grid-template-columns:1fr}.top-actions .btn:first-of-type{display:none}}
</style></head><body><div class="shell"><aside><div class="brand"><div class="mark">K</div><div><b>KIS Trading LAB</b><small>Control Center</small></div></div><nav class="nav"><button class="active" data-page="overview"><i>⌂</i><span>종합현황</span></button><button data-page="automation"><i>◉</i><span>자동매매</span></button><button data-page="quant"><i>⌁</i><span>퀀트분석</span></button><button data-page="performance"><i>↗</i><span>성과</span></button><button data-page="system"><i>⚙</i><span>시스템관리</span></button></nav><div class="aside-foot"><div class="mode">KIS VTS MODE<br><small>모의투자 서버 전용</small></div><a class="back" href="/ui/dashboard">← 트레이딩 화면</a></div></aside><main><header class="top"><div class="title"><h1 id="pageTitle">종합현황</h1><p id="pageCaption">운영 데이터와 자동매매 상태를 한눈에 확인합니다</p></div><div class="top-actions"><span class="health" id="health">시스템 정상</span><button class="btn" onclick="loadAll()">↻ 새로고침</button><a class="btn primary" href="/ui/dashboard" style="text-decoration:none">트레이딩 화면</a></div></header><div class="content"><div class="notice" id="notice"></div>
<section class="page active" id="overview"><div class="page-head"><div><h2>오늘의 운영 현황</h2><p>수집된 데이터, 분석 결과와 자동매매 준비 상태입니다.</p></div><button class="btn primary" onclick="runJob('daily_pipeline')">통합 파이프라인 실행</button></div><div class="kpis"><div class="card kpi"><div class="label">자동매매 대상</div><div class="value"><span id="kWatch">-</span><small> 종목</small></div></div><div class="card kpi"><div class="label">퀀트 시그널</div><div class="value" id="kSignal">-</div></div><div class="card kpi"><div class="label">매수 후보</div><div class="value" id="kBuy">-</div></div><div class="card kpi"><div class="label">모의주문</div><div class="value" id="kOrders">-</div></div><div class="card kpi"><div class="label">평균 백테스트 수익률</div><div class="value" id="kReturn">-</div></div></div><div class="grid"><article class="panel"><div class="panel-head"><h3>데이터 최신성</h3><button class="btn" onclick="runJob('collect_watchlist_data')">지금 수집</button></div><div id="freshness"></div></article><article class="panel"><div class="panel-head"><h3>자동매매 상태</h3><span class="pill" id="autoPill">대기</span></div><div id="autoSummary"></div><div class="pipeline"><div class="stage"><span>1</span><b>데이터 수집</b></div><div class="stage"><span>2</span><b>퀀트 분석</b></div><div class="stage"><span>3</span><b>백테스트</b></div></div></article></div></section>
<section class="page" id="automation"><div class="page-head"><div><h2>자동매매</h2><p>대상종목과 위험 한도를 설정하고 주문 후보를 모의 생성합니다.</p></div><button class="btn primary" onclick="runJob('auto_trade_dry_run')">주문 후보 생성</button></div><div class="grid"><article class="panel"><div class="panel-head"><h3>대상종목 설정</h3><span class="muted">관심종목과 자동 동기화</span></div><div id="universe"></div></article><article class="panel"><div class="panel-head"><h3>위험·매매 설정</h3><span class="pill ok">DRY RUN</span></div><div class="form-grid"><label class="field-label">최대 보유종목<input id="maxPositions" type="number" class="field"></label><label class="field-label">종목당 최대금액<input id="maxAmount" type="number" class="field"></label><label class="field-label">손절률 (%)<input id="stopLoss" type="number" class="field"></label><label class="field-label">익절률 (%)<input id="takeProfit" type="number" class="field"></label></div><div class="switch-row"><span><b>후보 생성 활성화</b><br><small class="muted">실제 주문은 항상 차단됩니다</small></span><input id="automationEnabled" type="checkbox"></div><button class="btn primary" onclick="saveSettings()">설정 저장</button></article></div><article class="panel" style="margin-top:11px"><div class="panel-head"><h3>최근 주문 후보</h3></div><div id="candidates" class="empty">주문 후보 생성을 실행하세요.</div></article></section>
<section class="page" id="quant"><div class="page-head"><div><h2>퀀트분석</h2><p>기술지표 기반 복합점수와 전략 성과를 비교합니다.</p></div><div class="toolbar"><button class="btn" onclick="runJob('analyze_watchlist')">시그널 분석</button><button class="btn primary" onclick="runJob('backtest_watchlist')">백테스트 실행</button></div></div><div class="grid equal"><article class="panel"><div class="panel-head"><h3>퀀트 시그널</h3><span class="muted">점수 높은 순</span></div><div class="table-wrap" id="signals"></div></article><article class="panel"><div class="panel-head"><h3>백테스트 결과</h3><span class="muted">최근 실행 순</span></div><div class="table-wrap" id="backtests"></div></article></div></section>
<section class="page" id="performance"><div class="page-head"><div><h2>성과</h2><p>전략 수익률, 위험과 모의매매 활동을 분석합니다.</p></div></div><div class="kpis"><div class="card kpi"><div class="label">백테스트 횟수</div><div class="value" id="pTests">-</div></div><div class="card kpi"><div class="label">평균 수익률</div><div class="value" id="pReturn">-</div></div><div class="card kpi"><div class="label">모의매매 건수</div><div class="value" id="pOrders">-</div></div></div><div class="grid"><article class="panel"><div class="panel-head"><h3>종목별 백테스트 성과</h3></div><div id="performanceBars"></div></article><article class="panel"><div class="panel-head"><h3>리밸런싱 준비</h3></div><p class="muted">활성 대상종목과 퀀트 시그널을 기준으로 후보를 계산합니다.</p><button class="btn primary" onclick="runJob('auto_trade_dry_run')">리밸런싱 후보 계산</button></article></div></section>
<section class="page" id="system"><div class="page-head"><div><h2>시스템관리</h2><p>배치 실행, 스케줄과 시스템 이벤트를 관리합니다.</p></div></div><div class="grid equal"><article class="panel"><div class="panel-head"><h3>주문 안전장치</h3></div><div id="orderSafety"></div></article><article class="panel"><div class="panel-head"><h3>최근 Reconciliation</h3></div><div id="reconciliationStatus"></div></article></div><div class="grid"><article class="panel"><div class="panel-head"><h3>배치 작업</h3></div><div class="job-list" id="jobs"></div></article><article class="panel"><div class="panel-head"><h3>스케줄 설정</h3></div><label class="field-label">분석 Cron 스케줄<input id="schedule" class="field"></label><p class="muted">설정은 저장되며 현재 배치는 수동 실행 방식입니다.</p><button class="btn" onclick="saveSettings()">스케줄 저장</button></article></div><div class="grid"><article class="panel"><div class="panel-head"><h3>배치 실행 이력</h3></div><div class="table-wrap" id="jobRuns"></div></article><article class="panel"><div class="panel-head"><h3>시스템 로그</h3><div class="log-filter"><button class="btn active" onclick="filterLogs('ALL',this)">전체</button><button class="btn" onclick="filterLogs('ERROR',this)">오류</button></div></div><div class="table-wrap" id="logs"></div></article></div></section>
</div></main></div><script>
const $=id=>document.getElementById(id),api=(u,o)=>fetch(u,o).then(async r=>{const d=await r.json();if(!r.ok)throw Error(Array.isArray(d.detail)?d.detail.map(x=>x.loc.slice(1).join('.')+': '+x.msg).join('; '):(d.detail||'요청에 실패했습니다'));return d}),fmt=v=>v==null?'-':Number(v).toLocaleString('ko-KR'),pct=v=>v==null?'-':`${(Number(v)*100).toFixed(2)}%`,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),table=(heads,rows)=>`<table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${heads.length}" class="empty">데이터가 없습니다</td></tr>`}</tbody></table>`;let state={},allLogs=[];
const pageMeta={overview:['종합현황','운영 데이터와 자동매매 상태를 한눈에 확인합니다'],automation:['자동매매','대상종목, 위험 설정과 모의 실행을 관리합니다'],quant:['퀀트분석','시그널과 백테스트 결과를 비교합니다'],performance:['성과','전략 수익률과 활동을 분석합니다'],system:['시스템관리','배치, 스케줄과 로그를 관리합니다']};document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button,.page').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(b.dataset.page).classList.add('active');$('pageTitle').textContent=pageMeta[b.dataset.page][0];$('pageCaption').textContent=pageMeta[b.dataset.page][1]});
function notify(msg,error=false){const n=$('notice');n.textContent=msg;n.style.borderColor=error?'#713043':'#285141';n.style.background=error?'#2b1520':'#10251f';n.style.color=error?'#ff91a0':'#7ce3c1';n.classList.add('show');clearTimeout(window.noticeTimer);window.noticeTimer=setTimeout(()=>n.classList.remove('show'),5000)}
async function loadAll(){try{const [o,s,b,u,r,l]=await Promise.all([api('/api/operations/overview'),api('/api/operations/signals'),api('/api/operations/backtests'),api('/api/operations/universe'),api('/api/operations/job-runs?limit=50'),api('/api/operations/logs?limit=100')]);state={o,s:s.items,b:b.items,u:u.items,r:r.items};allLogs=l.items;render();$('health').textContent='시스템 정상'}catch(e){$('health').textContent='확인 필요';notify(e.message,true)}}
function render(){const {o,s,b,u,r}=state,avg=o.average_backtest_return;$('kWatch').textContent=u.filter(x=>x.enabled).length;$('kSignal').textContent=o.signal_count;$('kBuy').textContent=o.buy_signal_count;$('kOrders').textContent=o.mock_order_count;$('kReturn').textContent=pct(avg);$('pTests').textContent=o.backtest_count;$('pReturn').textContent=pct(avg);$('pOrders').textContent=o.mock_order_count;$('autoPill').textContent=o.automation.automation_enabled?'활성':'대기';$('autoPill').className=`pill ${o.automation.automation_enabled?'ok':''}`;$('autoSummary').innerHTML=`<div class="state-box"><span><strong>${o.automation.automation_enabled?'후보 생성 활성':'수동 대기'}</strong><br><small class="muted">최대 ${o.automation.max_positions}종목 · 종목당 ${fmt(o.automation.max_order_amount)}원</small></span><span class="pill ok">KIS VTS</span></div>`;$('freshness').innerHTML=o.data_status.map(x=>`<div class="state-box" style="margin-top:7px"><span class="stock"><b>${esc(x.stock_name)}</b><small>${x.stock_code} · ${fmt(x.data_points)}건</small></span><span><b>${x.latest_trade_date||'-'}</b><div class="bar"><i style="width:${x.latest_trade_date?'100':'5'}%"></i></div></span></div>`).join('')||'<div class="empty">대상종목이 없습니다.</div>';
$('maxPositions').value=o.automation.max_positions;$('maxAmount').value=o.automation.max_order_amount;$('stopLoss').value=o.automation.stop_loss_rate;$('takeProfit').value=o.automation.take_profit_rate;$('automationEnabled').checked=o.automation.automation_enabled;$('schedule').value=o.automation.analysis_schedule;$('universe').innerHTML=u.map(x=>`<div class="universe-row"><input id="en-${x.stock_code}" type="checkbox" ${x.enabled?'checked':''}><span class="stock"><b>${esc(x.stock_name)}</b><small>${x.stock_code}</small></span><select id="st-${x.stock_code}" class="field"><option>LAB Strategy v1</option></select><input id="wt-${x.stock_code}" class="field" type="number" min="1" max="100" placeholder="비중 %" value="${x.target_weight??''}"><button class="btn save-universe" onclick="saveUniverse('${x.stock_code}')">저장</button></div>`).join('')||'<div class="empty">트레이딩 화면에서 관심종목을 등록하세요.</div>';
$('signals').innerHTML=table(['종목','기준일','Signal','점수'],s.map(x=>`<tr><td><b>${esc(x.stock_name)}</b><br><small class="muted">${x.stock_code}</small></td><td>${x.as_of_date||'-'}</td><td class="${x.signal}">${x.signal}</td><td class="num">${x.score}</td></tr>`));$('backtests').innerHTML=table(['종목','수익률','MDD','거래'],b.map(x=>`<tr><td>${x.stock_code}</td><td class="${x.total_return>=0?'BUY':'SELL'}">${pct(x.total_return)}</td><td>${pct(x.mdd)}</td><td class="num">${x.trade_count}</td></tr>`));$('performanceBars').innerHTML=b.slice(0,10).map(x=>{const w=Math.min(100,Math.abs(x.total_return*100));return `<div style="margin:12px 0"><div style="display:flex;justify-content:space-between;font-size:11px"><b>${x.stock_code}</b><span class="${x.total_return>=0?'BUY':'SELL'}">${pct(x.total_return)}</span></div><div class="bar"><i style="width:${w}%;background:${x.total_return>=0?'var(--red)':'var(--blue)'}"></i></div></div>`}).join('')||'<div class="empty">백테스트 결과가 없습니다.</div>';
$('jobs').innerHTML=o.latest_jobs.map(j=>`<div class="job"><span><b>${esc(j.description)}</b><small>${j.latest_run?`${j.latest_run.status} · ${j.latest_run.finished_at?.slice(0,19)||'실행 중'}`:'실행 이력 없음'}</small></span><button class="btn" onclick="runJob('${j.job_name}')">실행</button></div>`).join('');$('jobRuns').innerHTML=table(['작업','상태','성공','실패','완료시각'],r.map(x=>`<tr><td>${esc(x.job_name)}</td><td><span class="pill ${x.status==='success'?'ok':x.status==='partial'?'partial':'fail'}">${x.status}</span></td><td>${x.processed_count}</td><td>${x.error_count}</td><td>${x.finished_at?.slice(0,19)||'-'}</td></tr>`));const safe=o.order_safety;$('orderSafety').innerHTML=`<div class="state-box"><span><strong>실전주문: BLOCKED</strong><br><small class="muted">환경 ${esc(safe.environment)} · 주문 ${safe.paper_order_enabled&&safe.vts_submit_enabled?'명시적 허용':'기본 차단'}</small></span><span class="pill ok">VTS ONLY</span></div>`;const rec=o.latest_reconciliation;$('reconciliationStatus').innerHTML=rec?`<div class="state-box"><span><strong>${rec.mismatch||rec.manual_review_required?'확인 필요':'정합성 확인'}</strong><br><small class="muted">일치 ${rec.matched} · 보정 ${rec.corrected} · 불일치 ${rec.mismatch} · 수동검토 ${rec.manual_review_required}</small></span><span class="pill ${rec.mismatch||rec.manual_review_required?'partial':'ok'}">${rec.created_at.slice(0,19)}</span></div>`:'<div class="empty">아직 실행된 Reconciliation이 없습니다.</div>';renderLogs(allLogs)}
function renderLogs(items){$('logs').innerHTML=table(['시간','레벨','메시지'],items.map(x=>`<tr><td>${x.created_at.slice(0,19)}</td><td class="${x.level==='ERROR'?'SELL':''}">${x.level}</td><td>${esc(x.message)}</td></tr>`))}function filterLogs(level,btn){document.querySelectorAll('.log-filter button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');renderLogs(level==='ALL'?allLogs:allLogs.filter(x=>x.level===level))}
async function saveSettings(){try{await api('/api/operations/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({automation_enabled:$('automationEnabled').checked,dry_run:true,max_positions:Number($('maxPositions').value),max_order_amount:Number($('maxAmount').value),stop_loss_rate:Number($('stopLoss').value),take_profit_rate:Number($('takeProfit').value),analysis_schedule:$('schedule').value})});notify('운영 설정을 저장했습니다.');loadAll()}catch(e){notify(e.message,true)}}async function saveUniverse(code){try{const weight=$(`wt-${code}`).value;await api(`/api/operations/universe/${code}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:$(`en-${code}`).checked,strategy_name:$(`st-${code}`).value,target_weight:weight?Number(weight):null})});notify(`${code} 대상종목 설정을 저장했습니다.`);loadAll()}catch(e){notify(e.message,true)}}async function runJob(name){try{notify(`${name} 작업을 실행하고 있습니다.`);const r=await api(`/api/operations/jobs/${name}/run`,{method:'POST'});notify(`${name}: ${r.status} · ${r.items.length}건 처리`);if(name==='auto_trade_dry_run')$('candidates').innerHTML=table(['종목','Signal','점수','목표비중','최대금액'],r.items.map(x=>`<tr><td>${esc(x.stock_name)}</td><td class="${x.signal}">${x.signal}</td><td>${x.score}</td><td>${x.target_weight??'-'}%</td><td>${fmt(x.max_order_amount)}원</td></tr>`));loadAll()}catch(e){notify(e.message,true)}}loadAll();
</script></body></html>"""
